import{_ as t,o as i,c as a,a3 as s}from"./chunks/framework.B5WAEDB7.js";const h=JSON.parse('{"title":"Autonomous Project Delivery and Pilot Process","description":"A transparent, house-building-style process for autonomous short-distance transport projects from discovery through integration, validation, pilot and scale.","frontmatter":{"title":"Autonomous Project Delivery and Pilot Process","description":"A transparent, house-building-style process for autonomous short-distance transport projects from discovery through integration, validation, pilot and scale.","status":"design guidance","content_type":"delivery","keywords":["delivery process","pilot","site assessment","integration","calibration","validation","operations metrics","evidence pack"],"scope":"Planning and delivery method for WheelOS short-distance autonomous transport projects","decision_summary":"Break the project into reviewable stages with customer-visible deliverables, exit criteria and unresolved boundaries. Do not advance without passing the previous gate.","best_for":["controlled-site pilots","fixed-route transport","vehicle and chassis integration","measurable operating metrics"],"not_for":["deployment without site assessment","operating commitments before chassis confirmation","production claims without evidence"],"next_action":"Start with application discovery and define the task, operating boundary, vehicle conditions, acceptance metrics and stage owners.","cta_url":"mailto:support@wheelos.cn?subject=WheelOS%20pilot%20delivery%20plan"},"headers":[],"relativePath":"en/solutions/delivery-process.md","filePath":"en/solutions/delivery-process.md","lastUpdated":1794216847000}'),o={name:"en/solutions/delivery-process.md"};function r(n,e,d,l,c,p){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="autonomous-project-delivery-and-pilot-process" tabindex="-1">Autonomous Project Delivery and Pilot Process <a class="header-anchor" href="#autonomous-project-delivery-and-pilot-process" aria-label="Permalink to &quot;Autonomous Project Delivery and Pilot Process&quot;">​</a></h1><blockquote><p>An autonomous-driving project is easier to trust when it is built like a house: inspect the ground first, then design, build, inspect and move in. Customers should see outputs, issues and evidence at each step instead of buying an opaque “finished product” and inheriting the integration risk.</p></blockquote><h2 id="seven-customer-visible-stages" tabindex="-1">Seven customer-visible stages <a class="header-anchor" href="#seven-customer-visible-stages" aria-label="Permalink to &quot;Seven customer-visible stages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>What the customer sees</th><th>Key deliverables</th><th>Gate to continue</th></tr></thead><tbody><tr><td>1. Application discovery</td><td>Tasks, shifts, routes, cargo, handoffs and current cost</td><td>Application screen and preliminary value case</td><td>Frequent work, operable demand and a clear owner</td></tr><tr><td>2. Boundary design</td><td>ODD, stops, routes, risks and regulatory issues</td><td>Project boundary, responsibility matrix and draft acceptance metrics</td><td>Risks acceptable and responsibilities explicit</td></tr><tr><td>3. Vehicle and sensors</td><td>Chassis, sensor placement, compute and interfaces</td><td>Hardware configuration, interface list and installation plan</td><td>Drive-by-wire and critical CAN signals confirmed</td></tr><tr><td>4. Software and data integration</td><td>Time sync, frames, localization, perception, planning and control path</td><td>Configuration, calibration records, data recording and system checklist</td><td>Data path and baseline functions are replayable</td></tr><tr><td>5. Replay and controlled-site validation</td><td>Test scenarios, metrics, failure samples and issue list</td><td>Validation report, failure cases and fix records</td><td>Agreed thresholds met and boundaries documented</td></tr><tr><td>6. Pilot operation</td><td>Daily tasks, staffing, exception handling and operations dashboard</td><td>Operating logs, KPIs, issue closure and stage review</td><td>Stable operation and evidence collection</td></tr><tr><td>7. Assessment and expansion</td><td>Whether the solution is repeatable, cost-effective and safe to extend</td><td>Evidence pack, retrospective and expansion recommendation</td><td>Reviewable results and explicit residual risk</td></tr></tbody></table><h2 id="make-every-stage-visible" tabindex="-1">Make every stage visible <a class="header-anchor" href="#make-every-stage-visible" aria-label="Permalink to &quot;Make every stage visible&quot;">​</a></h2><h3 id="the-customer-should-be-able-to-inspect" tabindex="-1">The customer should be able to inspect <a class="header-anchor" href="#the-customer-should-be-able-to-inspect" aria-label="Permalink to &quot;The customer should be able to inspect&quot;">​</a></h3><ul><li>Site photos, route map and operating design domain.</li><li>Sensor and chassis-interface lists.</li><li>Time-sync, calibration and data-recording checks.</li><li>Replay data, scenario list, metrics and failure samples.</li><li>Issue list, fixes and unresolved risks.</li><li>Pilot dashboard and stage retrospective.</li></ul><h3 id="wheelos-should-provide" tabindex="-1">WheelOS should provide <a class="header-anchor" href="#wheelos-should-provide" aria-label="Permalink to &quot;WheelOS should provide&quot;">​</a></h3><ul><li>Explicit project stages and owners.</li><li>Inputs, outputs and acceptance conditions for each stage.</li><li>Standard configurations, interface documentation and test-record formats.</li><li>Technical risks, dependencies and unverified boundaries.</li><li>Traceable versions, configuration and evidence indexes.</li></ul><h2 id="metrics-every-pilot-must-record" tabindex="-1">Metrics every pilot must record <a class="header-anchor" href="#metrics-every-pilot-must-record" aria-label="Permalink to &quot;Metrics every pilot must record&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Baseline to define first</th><th>Purpose</th></tr></thead><tbody><tr><td>Transport frequency</td><td>Tasks per day, shifts and peak windows</td><td>Test real demand and vehicle utilization</td></tr><tr><td>Labor input</td><td>Driver, material-handler, dispatch and intervention hours</td><td>Compare with the post-pilot process</td></tr><tr><td>Vehicle utilization</td><td>Productive run time, waiting and empty running</td><td>Assess single-vehicle economics</td></tr><tr><td>On-time rate</td><td>Tasks completed inside the agreed window</td><td>Measure operational availability</td></tr><tr><td>Exceptions</td><td>Interventions, emergency stops, blocked paths and manual recovery per 100 tasks</td><td>Expose system and process weaknesses</td></tr><tr><td>Unit cost</td><td>Cost per task, kilometer or pallet</td><td>Assess commercial viability</td></tr><tr><td>Safety events</td><td>Collisions, near misses, violations and site risks, classified</td><td>Trigger stop and corrective action</td></tr></tbody></table><p>These are pilot-evaluation metrics, not current WheelOS performance measurements. Evidence exists only after an actual project records and reviews them.</p><h2 id="do-not-skip-stages" tabindex="-1">Do not skip stages <a class="header-anchor" href="#do-not-skip-stages" aria-label="Permalink to &quot;Do not skip stages&quot;">​</a></h2><ul><li>Do not commit to vehicle integration before chassis and drive-by-wire interfaces are confirmed.</li><li>Do not infer route performance before time sync, frames and calibration are checked.</li><li>Do not make site-validation conclusions without replay and failure samples.</li><li>Do not make business-impact conclusions without a baseline and operating metrics.</li><li>Do not upgrade a pilot to “verified” or a production capability without a complete evidence record.</li></ul><h2 id="evidence-pack-at-pilot-close" tabindex="-1">Evidence pack at pilot close <a class="header-anchor" href="#evidence-pack-at-pilot-close" aria-label="Permalink to &quot;Evidence pack at pilot close&quot;">​</a></h2><ol><li>Task definition and operating design domain.</li><li>Software, configuration, vehicle and sensor versions.</li><li>Raw logs, recordings and critical replays.</li><li>Baseline, target, actual metrics and statistical method.</li><li>Exceptions, interventions, failure samples and corrective actions.</li><li>Uncovered scenarios, regulatory boundary and residual risk.</li><li>Reviewer and next-stage recommendation.</li></ol><div class="solution-cta"><div><h2>See how the project is built, step by step</h2><p>Share the application and vehicle context. We will define deliverables and exit criteria across discovery, boundaries, integration, validation and pilot.</p></div><div class="solution-actions"><a class="primary" href="mailto:support@wheelos.cn?subject=WheelOS%20pilot%20delivery%20plan">Discuss a pilot plan</a><a href="/en/solutions/applications">Assess the application first</a></div></div>',17)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
